-- G7 event_daily_range_coverage (Addendum 11): the read-only queries that follow the builds, written 2026-10-30 before any run. Order: QUERY M (the METHOD CHECK on the stored tables), QUERY D (diagnostics of the rebuilt day-lists), then QUERY 0 and QUERY 1 (the readouts of ARM 0 and ARM 1).
-- READOUT QUERY M (method check, stored tables): the coverage at k_ref (bin <= 118, that is |ret| / v64 below 1.19, the original readout) computed DIRECTLY from market_prices and vol_estimators for the days of flag_days and ctrl_days: ret = close / previous close - 1 with the previous close taken within the same window as the original build (from 15 days before January 1 of the year); v64 > 0; days from 2004-01-01 to 2026-07-31; era A is 2004-2018.
WITH fl AS (SELECT security_id, d, $$1_flag_day0_or_p1$$ AS grp FROM flag_days WHERE has_0 OR has_p1 UNION ALL SELECT security_id, d, $$2_flag_p1_only$$ FROM flag_days WHERE has_p1 AND NOT has_0 AND NOT has_m1 UNION ALL SELECT security_id, d, $$3_control_25_to_39$$ FROM ctrl_days), x AS (SELECT f.grp, CASE WHEN f.d <= $$2018-12-31$$::date THEN $$A_2004_2018$$ ELSE $$B_2019_2026$$ END AS era, p1.adjusted_close / p0.adjusted_close - 1 AS ret, ve.v64 FROM fl f JOIN market_prices p1 ON p1.security_id = f.security_id AND p1.price_date = f.d JOIN LATERAL (SELECT p.adjusted_close FROM market_prices p WHERE p.security_id = f.security_id AND p.price_date < f.d AND p.price_date >= make_date(EXTRACT(YEAR FROM f.d)::int, 1, 1) - 15 ORDER BY p.price_date DESC LIMIT 1) p0 ON true JOIN vol_estimators ve ON ve.security_id = f.security_id AND ve.d = f.d WHERE f.security_id <> (SELECT id FROM securities WHERE ticker = $$SPY$$) AND f.d >= $$2004-01-01$$::date AND f.d <= $$2026-07-31$$::date AND ve.v64 > 0 AND p1.adjusted_close IS NOT NULL AND p0.adjusted_close IS NOT NULL) SELECT $$1_stored$$ AS arm, era, grp, COUNT(*) AS n_days, ROUND(AVG((FLOOR(ABS(ret) / v64 * 100)::int <= 118)::int)::numeric, 4) AS coverage_at_kref FROM x GROUP BY 1, 2, 3 ORDER BY 2, 3;

-- QUERY D (diagnostics): the stored day-lists against ARM 0 and ARM 0 against ARM 1, with distinct-key counts (the lesson of the premium rebuild).
SELECT (SELECT COUNT(*) FROM flag_days) AS flag_stored, (SELECT COUNT(DISTINCT (security_id, d)) FROM flag_days) AS flag_stored_keys, (SELECT COUNT(*) FROM flag_days_g7_arm0) AS flag_arm0, (SELECT COUNT(DISTINCT (security_id, d)) FROM flag_days_g7_arm0) AS flag_arm0_keys, (SELECT COUNT(*) FROM flag_days_g7_arm1) AS flag_arm1, (SELECT COUNT(DISTINCT (security_id, d)) FROM flag_days_g7_arm1) AS flag_arm1_keys, (SELECT COUNT(*) FROM flag_days_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM flag_days s WHERE s.security_id = a.security_id AND s.d = a.d)) AS flag_only_arm0, (SELECT COUNT(*) FROM flag_days s WHERE NOT EXISTS (SELECT 1 FROM flag_days_g7_arm0 a WHERE a.security_id = s.security_id AND a.d = s.d)) AS flag_only_stored, (SELECT COUNT(*) FROM flag_days_g7_arm0 a JOIN flag_days s ON s.security_id = a.security_id AND s.d = a.d WHERE a.has_m1 <> s.has_m1 OR a.has_0 <> s.has_0 OR a.has_p1 <> s.has_p1) AS flag_flags_differ, (SELECT COUNT(*) FROM flag_days_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM flag_days_g7_arm1 b WHERE b.security_id = a.security_id AND b.d = a.d)) AS flag_in_arm0_not_arm1, (SELECT COUNT(*) FROM ctrl_days) AS ctrl_stored, (SELECT COUNT(DISTINCT (security_id, d)) FROM ctrl_days) AS ctrl_stored_keys, (SELECT COUNT(*) FROM ctrl_days_g7_arm0) AS ctrl_arm0, (SELECT COUNT(DISTINCT (security_id, d)) FROM ctrl_days_g7_arm0) AS ctrl_arm0_keys, (SELECT COUNT(*) FROM ctrl_days_g7_arm1) AS ctrl_arm1, (SELECT COUNT(*) FROM ctrl_days_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM ctrl_days s WHERE s.security_id = a.security_id AND s.d = a.d)) AS ctrl_only_arm0, (SELECT COUNT(*) FROM ctrl_days s WHERE NOT EXISTS (SELECT 1 FROM ctrl_days_g7_arm0 a WHERE a.security_id = s.security_id AND a.d = s.d)) AS ctrl_only_stored, (SELECT COUNT(*) FROM ctrl_days_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM ctrl_days_g7_arm1 b WHERE b.security_id = a.security_id AND b.d = a.d)) AS ctrl_in_arm0_not_arm1;

-- READOUT QUERY 0 (ARM 0): the coverage at k_ref (bin <= 118, that is |ret| / v64 below 1.19, the original readout) computed DIRECTLY from market_prices and vol_estimators for the days of flag_days_g7_arm0 and ctrl_days_g7_arm0: ret = close / previous close - 1 with the previous close taken within the same window as the original build (from 15 days before January 1 of the year); v64 > 0; days from 2004-01-01 to 2026-07-31; era A is 2004-2018.
WITH fl AS (SELECT security_id, d, $$1_flag_day0_or_p1$$ AS grp FROM flag_days_g7_arm0 WHERE has_0 OR has_p1 UNION ALL SELECT security_id, d, $$2_flag_p1_only$$ FROM flag_days_g7_arm0 WHERE has_p1 AND NOT has_0 AND NOT has_m1 UNION ALL SELECT security_id, d, $$3_control_25_to_39$$ FROM ctrl_days_g7_arm0), x AS (SELECT f.grp, CASE WHEN f.d <= $$2018-12-31$$::date THEN $$A_2004_2018$$ ELSE $$B_2019_2026$$ END AS era, p1.adjusted_close / p0.adjusted_close - 1 AS ret, ve.v64 FROM fl f JOIN market_prices p1 ON p1.security_id = f.security_id AND p1.price_date = f.d JOIN LATERAL (SELECT p.adjusted_close FROM market_prices p WHERE p.security_id = f.security_id AND p.price_date < f.d AND p.price_date >= make_date(EXTRACT(YEAR FROM f.d)::int, 1, 1) - 15 ORDER BY p.price_date DESC LIMIT 1) p0 ON true JOIN vol_estimators ve ON ve.security_id = f.security_id AND ve.d = f.d WHERE f.security_id <> (SELECT id FROM securities WHERE ticker = $$SPY$$) AND f.d >= $$2004-01-01$$::date AND f.d <= $$2026-07-31$$::date AND ve.v64 > 0 AND p1.adjusted_close IS NOT NULL AND p0.adjusted_close IS NOT NULL) SELECT $$2_arm0$$ AS arm, era, grp, COUNT(*) AS n_days, ROUND(AVG((FLOOR(ABS(ret) / v64 * 100)::int <= 118)::int)::numeric, 4) AS coverage_at_kref FROM x GROUP BY 1, 2, 3 ORDER BY 2, 3;

-- READOUT QUERY 1 (ARM 1): the coverage at k_ref (bin <= 118, that is |ret| / v64 below 1.19, the original readout) computed DIRECTLY from market_prices and vol_estimators for the days of flag_days_g7_arm1 and ctrl_days_g7_arm1: ret = close / previous close - 1 with the previous close taken within the same window as the original build (from 15 days before January 1 of the year); v64 > 0; days from 2004-01-01 to 2026-07-31; era A is 2004-2018.
WITH fl AS (SELECT security_id, d, $$1_flag_day0_or_p1$$ AS grp FROM flag_days_g7_arm1 WHERE has_0 OR has_p1 UNION ALL SELECT security_id, d, $$2_flag_p1_only$$ FROM flag_days_g7_arm1 WHERE has_p1 AND NOT has_0 AND NOT has_m1 UNION ALL SELECT security_id, d, $$3_control_25_to_39$$ FROM ctrl_days_g7_arm1), x AS (SELECT f.grp, CASE WHEN f.d <= $$2018-12-31$$::date THEN $$A_2004_2018$$ ELSE $$B_2019_2026$$ END AS era, p1.adjusted_close / p0.adjusted_close - 1 AS ret, ve.v64 FROM fl f JOIN market_prices p1 ON p1.security_id = f.security_id AND p1.price_date = f.d JOIN LATERAL (SELECT p.adjusted_close FROM market_prices p WHERE p.security_id = f.security_id AND p.price_date < f.d AND p.price_date >= make_date(EXTRACT(YEAR FROM f.d)::int, 1, 1) - 15 ORDER BY p.price_date DESC LIMIT 1) p0 ON true JOIN vol_estimators ve ON ve.security_id = f.security_id AND ve.d = f.d WHERE f.security_id <> (SELECT id FROM securities WHERE ticker = $$SPY$$) AND f.d >= $$2004-01-01$$::date AND f.d <= $$2026-07-31$$::date AND ve.v64 > 0 AND p1.adjusted_close IS NOT NULL AND p0.adjusted_close IS NOT NULL) SELECT $$3_arm1$$ AS arm, era, grp, COUNT(*) AS n_days, ROUND(AVG((FLOOR(ABS(ret) / v64 * 100)::int <= 118)::int)::numeric, 4) AS coverage_at_kref FROM x GROUP BY 1, 2, 3 ORDER BY 2, 3;
